// Helpers for compatibility tests that read fixtures generated by past versions of Stello
// See fixtures/compat/README.md

import {inject} from 'vitest'

import {binary_response, FetchMock} from './unit_utils'
import {url64_to_buffer} from '@/services/utils/coding'


// Fixtures generated by the app for each version
export interface AppFixture {
    version:string
    keys:{shared_secret:string, secret:string, resp_key_public:string}
    ids:{profile:string, msg:string, copy:string, contact:string, form:string, resp_token:string,
        sections:Record<'text'|'images'|'file'|'video'|'chart'|'page', string>}
    view_hash:string
    encrypted_address:string
    storage:Record<string, string>
    backup:string
}


// All fixture files keyed by version then file name (read by compat_setup.ts)
declare module 'vitest' {
    export interface ProvidedContext {
        compat_fixtures:Record<string, Record<string, unknown>>
    }
}
const fixtures = inject('compat_fixtures')


export function compat_versions(fixture:string, missing?:string):string[]{
    // List versions (oldest first) that have the given fixture file (and optionally lack another)
    return Object.keys(fixtures)
        .filter(version => fixture in fixtures[version]!
            && (!missing || !(missing in fixtures[version]!)))
        .sort((a, b) => a.localeCompare(b, undefined, {numeric: true}))
}


export function read_fixture<T>(version:string, fixture:string):T{
    // Read a fixture file for the given version
    return fixtures[version]![fixture] as T
}


export function serve_app_fixture(fetch_mock:FetchMock, app:AppFixture):void{
    // Serve everything the app uploaded to storage at the dev paths the displayer requests
    for (const [key, value] of Object.entries(app.storage)){
        if (key === 'config/displayer'){
            fetch_mock.routes['/dev/config/_user/config'] = binary_response(url64_to_buffer(value))
        } else if (key === 'config/subscribe'){
            fetch_mock.routes['/dev/config/_user/subscribe'] = new Response(value)
        } else if (!key.startsWith('config/')){
            fetch_mock.routes[`/dev/messages/_user/${key}`] =
                binary_response(url64_to_buffer(value))
        }
    }
}
